+static const char *chunkify_string(sinsp_span_t *sinsp_span, const char *key, int64_t cpu_id, int64_t proc_id, uint16_t fc_idx) {
+    int64_t proc_key = 0;
+
 #ifdef SS_MEMORY_STATISTICS
     total_chunked_strings++;
