+        if (proc_string && strcmp(proc_string, key) == 0) {
+#ifdef SS_MEMORY_STATISTICS
+            proc_info_hits++;
+#endif
+            return proc_string;
+        }
+    }
+
+    char *chunk_string = (char *) wmem_map_lookup(sinsp_span->str_chunk, key);
+
     if (!chunk_string) {
 #ifdef SS_MEMORY_STATISTICS
